  + name : string
}

class AdvisedExamination {
  + name : string
}

class FreeExamination {
  + name : string
}

class Diagnosis {
  + date : date
}

class Treatment {
  + date : date
}

class Doctor {}

class Patient {}

Hospital "1" -- "*" ExaminationType : has permission for
Hospital "1" -- "*" Doctor : employs
Hospital "1" -- "*" Examination : performs
Doctor "1" -- "*" Diagnosis : poses
Doctor "1" -- "*" Treatment : defines
Patient "1" -- "*" Diagnosis : receives
Diagnosis "1" -- "1" ProblemType : for
Diagnosis "1" -- "1" Treatment : leads to
Treatment "1" -- "1" TreatmentPlan : based on
Treatment "1" -- "*" AdvisedExamination : includes
Treatment "1" -- "*" FreeExamination : includes
TreatmentPlan "1" -- "*" AdvisedExamination : lists
Examination "1" -- "1" ExaminationType : is of type
Examination "1" -- "0..1" Hospital : performed at

@enduml

